renderBackup=async function(){
  try{const d=await api('/api/admin/snapshots');setContent(`<div class="grid two"><div class="card"><div class="eyebrow">RESTORE POINTS</div><h3>Configuration Snapshots</h3><p>Create a server-side restore point before major changes.</p><label>Snapshot name<input id="snapName" placeholder="Before Police rollout"></label><button id="createSnapshot">CREATE RESTORE POINT</button><div class="snapshotList">${(d.snapshots||[]).map(s=>`<div class="snapshotRow"><div><b>${esc(s.name)}</b><small>${new Date(s.createdAt).toLocaleString()} · ${esc(s.createdBy)}</small></div><button data-snap-restore="${esc(s.id)}">RESTORE</button></div>`).join('')||'<div class="emptyState">No restore points yet.</div>'}</div></div><div class="card"><div class="eyebrow">PORTABLE BACKUP</div><h3>Export / Import</h3><p>Download a JSON backup for off-site storage, or restore a previously exported backup.</p><button id="exportBtn">DOWNLOAD FULL BACKUP</button><input id="restoreFile" type="file" accept=".json,application/json"><textarea id="restoreData" rows="10" placeholder="Backup JSON"></textarea><button class="danger" id="restoreBtn">VALIDATE & RESTORE</button></div></div>`);$('createSnapshot').onclick=async()=>{await api('/api/admin/snapshots',{method:'POST',body:JSON.stringify({name:$('snapName').value.trim()||'Manual restore point'})});notify('Restore point created');renderBackup()};document.querySelectorAll('[data-snap-restore]').forEach(b=>b.onclick=async()=>{if(!confirm('Restore this snapshot? Current configuration will be replaced.'))return;await api('/api/admin/snapshots/'+encodeURIComponent(b.dataset.snapRestore)+'/restore',{method:'POST',body:'{}'});notify('Snapshot restored');await refreshAll()});$('exportBtn').onclick=()=>location.href='/api/admin/export';$('restoreFile').onchange=async e=>{const f=e.target.files?.[0];if(f)$('restoreData').value=await f.text()};$('restoreBtn').onclick=async()=>{let data;try{data=JSON.parse($('restoreData').value)}catch{return alert('Backup JSON is invalid.')}if(!confirm('Restore this Guardian backup?'))return;await api('/api/admin/import',{method:'POST',body:JSON.stringify(data)});notify('Guardian backup restored');await refreshAll()}}catch(e){errorView('Backups / Restore Points',e)}
}

