renderServices=async function(){
 try{
  const [sd,ud]=await Promise.all([api('/api/admin/services'),api('/api/admin/users').catch(()=>({users:[]}))]);
  let services=sd.services||[], users=ud.users||[], selected=services[0]?.id||'', tab='callsigns', showImport=false;
  const saveAll=async()=>{await api('/api/admin/services',{method:'POST',body:JSON.stringify({services})});notify('Service directory saved')};
  const usedMap=()=>{const m=new Map();for(const u of users)for(const a of (u.serviceAssignments||[]))if(a.callsign)m.set(String(a.callsign).trim().toUpperCase(),u.displayName||u.username);return m};
  const ensureDirectory=svc=>{
    if(Array.isArray(svc.callsignDirectory))return;
    svc.callsignDirectory=(svc.manualCallsigns||[]).map((x,i)=>({id:'legacy-'+i,callsign:String(x),group:'General',division:'',description:'',active:true}));
  };
  const collectServiceIdentity=svc=>{
    if(!$('v54SvcName'))return;
    svc.name=$('v54SvcName').value.trim();svc.id=$('v54SvcId').value.trim();svc.shortCode=$('v54SvcCode').value.trim();svc.accentColor=$('v54SvcColour').value;svc.icon=$('v54SvcIcon').value.trim()||'◆';svc.enabled=$('v54SvcEnabled').checked;
  };
  const draw=()=>{
   if(!services.length){setContent(`<div class="card"><div class="sectionHead"><div><div class="eyebrow">SERVICE DIRECTORY</div><h3>No services configured</h3></div><button id="v54AddFirst">ADD SERVICE</button></div></div>`);$('v54AddFirst').onclick=()=>{services.push({id:'service-'+Date.now(),name:'New Service',enabled:true,accentColor:'#2f8ec7',ranks:[],divisions:[],roles:[],qualifications:[],callsignDirectory:[]});selected=services[0].id;draw()};return}
   const svc=services.find(x=>x.id===selected)||services[0];selected=svc.id;ensureDirectory(svc);const used=usedMap();const accent=svc.accentColor||'#2f8ec7';
   const rows=svc.callsignDirectory||[];const groups=[...new Set(rows.map(x=>(x.group||'General').trim()).filter(Boolean))].sort();const activeCount=rows.filter(x=>x.active!==false&&x.callsign).length;const assigned=rows.filter(x=>used.has(String(x.callsign||'').toUpperCase())).length;
   let body='';
   if(tab==='service')body=`<section class="card v54Panel" style="--svc:${esc(accent)}"><div class="sectionHead"><div><div class="eyebrow">SERVICE PROFILE</div><h3>${esc(svc.name)}</h3><p>Identity and high-level setup for this FiveM emergency service.</p></div></div><div class="v54IdentityGrid"><label>Service name<input id="v54SvcName" value="${esc(svc.name||'')}"></label><label>Service ID<input id="v54SvcId" value="${esc(svc.id||'')}"></label><label>Short code<input id="v54SvcCode" value="${esc(svc.shortCode||'')}" placeholder="SFRS / NFRS / POLSCOT / SAS"></label><label>Accent colour<input id="v54SvcColour" type="color" value="${esc(accent)}"></label><label>Icon / badge<input id="v54SvcIcon" value="${esc(svc.icon||'◆')}"></label><label class="toggleCard compact"><input id="v54SvcEnabled" type="checkbox" ${svc.enabled!==false?'checked':''}> Service enabled</label></div><div class="saveBar"><button id="v54DeleteSvc" class="danger">DELETE SERVICE</button><button id="v54SaveSvc">SAVE SERVICE</button></div></section>`;
   if(tab==='ranks')body=`<section class="card v54Panel" style="--svc:${esc(accent)}"><div class="sectionHead"><div><div class="eyebrow">ORGANISATION</div><h3>Ranks, divisions & roles</h3><p>Keep service structure separate from callsigns so large Police/Fire/Ambulance directories stay manageable.</p></div></div><div class="two">${v49ListEditor('Ranks',svc.ranks||[],'ranks','Use your RP rank structure in display order.')}${v49ListEditor('Divisions / stations / departments',svc.divisions||[],'divisions','Examples: East Scotland, Northumberland, Response, Roads Policing.')}</div><div class="two">${v49ListEditor('Operational roles',svc.roles||[],'roles','Driver, OIC, Dispatcher, Response Officer, Paramedic...')}${v49ListEditor('Starter skills',svc.qualifications||[],'qualifications','Detailed qualifications are managed in Training & Qualifications.')}</div><div class="saveBar"><span>${(svc.ranks||[]).length} ranks · ${(svc.divisions||[]).length} divisions</span><button id="v54SaveOrg">SAVE ORGANISATION</button></div></section>`;
   if(tab==='callsigns')body=`<div class="v54CallsignStudio" style="--svc:${esc(accent)}"><section class="card v54Panel"><div class="sectionHead"><div><div class="eyebrow">MANUAL CALLSIGN DIRECTORY</div><h3>${esc(svc.name)}</h3><p>Enter the exact callsigns used on your FiveM server. Nothing is auto-generated or reformatted.</p></div><div class="buttonGroup"><button id="v54AddCallsign">+ ADD CALLSIGN</button><button id="v54ToggleImport" class="secondary">BULK PASTE</button></div></div><div class="v54MetricRow"><div><b>${rows.length}</b><span>Total records</span></div><div><b>${activeCount}</b><span>Active</span></div><div><b>${assigned}</b><span>Assigned</span></div><div><b>${Math.max(0,activeCount-assigned)}</b><span>Available</span></div></div>${showImport?`<div class="v54ImportBox"><div><b>Bulk paste callsigns</b><small>One per line. Optional format: CALLSIGN | GROUP | DIVISION | DESCRIPTION</small></div><textarea id="v54BulkText" rows="8" placeholder="J27P6 | Pump | East Scotland | Pump appliance\nSIERRA-01 | Response | Edinburgh | Response unit\nAMB-21 | Ambulance | East | Emergency ambulance"></textarea><div class="buttonGroup"><button id="v54ImportNow">IMPORT LIST</button><button id="v54CancelImport" class="secondary">CANCEL</button></div></div>`:''}<div class="v54DirectoryTools"><input id="v54CallsignSearch" placeholder="Search callsign, group, division or description"><select id="v54GroupFilter"><option value="">All groups</option>${groups.map(g=>`<option value="${esc(g)}">${esc(g)}</option>`).join('')}</select><select id="v54StateFilter"><option value="">All records</option><option value="active">Active only</option><option value="assigned">Assigned only</option><option value="free">Available only</option></select></div><div class="v54CallsignList"><div class="v54CallsignHeader"><span>Callsign</span><span>Group / Function</span><span>Division / Area</span><span>Description</span><span>Assignment</span><span>Active</span><span></span></div><div id="v54CallsignRows">${rows.map((r,i)=>{const key=String(r.callsign||'').toUpperCase(),owner=used.get(key);return `<div class="v54CallsignRow" data-v54-row="${i}" data-assigned="${owner?'1':'0'}"><input data-v54-call="${i}" value="${esc(r.callsign||'')}" placeholder="Callsign"><input data-v54-group="${i}" value="${esc(r.group||'General')}" placeholder="Pump / Response / Roads"><input data-v54-div="${i}" value="${esc(r.division||'')}" placeholder="East Scotland / Response"><input data-v54-desc="${i}" value="${esc(r.description||'')}" placeholder="Optional note"><span class="v54AssignState ${owner?'used':'free'}">${owner?`Assigned · ${esc(owner)}`:'Available'}</span><label class="miniToggle"><input data-v54-active="${i}" type="checkbox" ${r.active!==false?'checked':''}> Active</label><button class="danger iconBtn" data-v54-del="${i}">×</button></div>`}).join('')||'<div class="emptyState">No callsigns yet. Add one or paste your full service list.</div>'}</div></div><div class="saveBar"><span id="v54CallsignHint">Manual directory · exact server callsigns</span><button id="v54SaveCallsigns">SAVE CALLSIGNS</button></div></section><aside class="card v54Tips"><div class="eyebrow">GOOD STRUCTURE</div><h3>Keep large lists organised</h3><p>Use Group / Function and Division / Area rather than creating separate pages for every unit.</p><div class="v54Example"><b>Fire</b><span>Pump · Aerial · Command · Specialist · Water Rescue</span></div><div class="v54Example"><b>Police Scotland</b><span>Response · Roads Policing · CID · Specialist · Command</span></div><div class="v54Example"><b>Scottish Ambulance</b><span>Emergency Ambulance · RRV · Specialist · Command</span></div><div class="v54Example"><b>Northumberland / SFRS</b><span>Use Division / Area to separate service geography while keeping callsigns manual.</span></div></aside></div>`;
   setContent(`<div class="v54ServiceWorkspace"><aside class="card v54ServiceRail"><div class="eyebrow">SERVICES</div>${services.map(s=>`<button class="v54ServicePick ${s.id===selected?'active':''}" data-v54-svc="${esc(s.id)}" style="--svc:${esc(s.accentColor||'#2f8ec7')}"><span class="serviceAccentDot"></span><span><b>${esc(s.name)}</b><small>${esc(s.shortCode||s.id)} · ${s.enabled===false?'DISABLED':'ENABLED'}</small></span></button>`).join('')}<button id="v54AddService" class="v54AddService">+ ADD SERVICE</button></aside><main class="v54ServiceMain"><div class="settingsSubtabs v54Tabs"><button class="settingsSubtab ${tab==='service'?'active':''}" data-v54-tab="service">SERVICE<small>Identity & branding</small></button><button class="settingsSubtab ${tab==='ranks'?'active':''}" data-v54-tab="ranks">RANKS & ROLES<small>Hierarchy & structure</small></button><button class="settingsSubtab ${tab==='callsigns'?'active':''}" data-v54-tab="callsigns">CALLSIGNS<small>Manual directory</small></button></div>${body}</main></div>`);
   document.querySelectorAll('[data-v54-svc]').forEach(b=>b.onclick=()=>{selected=b.dataset.v54Svc;showImport=false;draw()});document.querySelectorAll('[data-v54-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.v54Tab;showImport=false;draw()});
   $('v54AddService').onclick=()=>{services.push({id:'service-'+Date.now(),name:'New Service',shortCode:'',enabled:true,accentColor:'#2f8ec7',icon:'◆',ranks:[],divisions:[],roles:[],qualifications:[],callsignDirectory:[]});selected=services.at(-1).id;tab='service';draw()};
   if(tab==='service'){$('v54SaveSvc').onclick=async()=>{const oldId=svc.id;collectServiceIdentity(svc);selected=svc.id;await saveAll();draw()};$('v54DeleteSvc').onclick=async()=>{if(!confirm(`Delete ${svc.name}?`))return;services=services.filter(x=>x!==svc);selected=services[0]?.id||'';await saveAll();draw()}}
   if(tab==='ranks'){
    const collectLists=()=>{for(const kind of ['ranks','divisions','roles','qualifications'])svc[kind]=[...document.querySelectorAll(`[data-v49-item^="${kind}:"]`)].map(x=>x.value.trim()).filter(Boolean)};
    document.querySelectorAll('[data-v49-add-list]').forEach(b=>b.onclick=()=>{collectLists();svc[b.dataset.v49AddList]=svc[b.dataset.v49AddList]||[];svc[b.dataset.v49AddList].push('');draw()});document.querySelectorAll('[data-v49-del-item]').forEach(b=>b.onclick=()=>{collectLists();const [k,i]=b.dataset.v49DelItem.split(':');svc[k].splice(+i,1);draw()});$('v54SaveOrg').onclick=async()=>{collectLists();await saveAll();draw()}
   }
   if(tab==='callsigns'){
    const collect=()=>{svc.callsignDirectory=[...document.querySelectorAll('[data-v54-row]')].map(row=>{const i=row.dataset.v54Row;return {id:rows[i]?.id||('cs-'+Date.now()+'-'+i),callsign:(document.querySelector(`[data-v54-call="${i}"]`)?.value||'').trim().toUpperCase(),group:(document.querySelector(`[data-v54-group="${i}"]`)?.value||'General').trim(),division:(document.querySelector(`[data-v54-div="${i}"]`)?.value||'').trim(),description:(document.querySelector(`[data-v54-desc="${i}"]`)?.value||'').trim(),active:!!document.querySelector(`[data-v54-active="${i}"]`)?.checked}}).filter(x=>x.callsign);svc.manualCallsigns=svc.callsignDirectory.map(x=>x.callsign);svc.callsignSets=[];};
    $('v54AddCallsign').onclick=()=>{collect();svc.callsignDirectory.push({id:'cs-'+Date.now(),callsign:'',group:'General',division:'',description:'',active:true});draw()};$('v54ToggleImport').onclick=()=>{collect();showImport=true;draw()};if($('v54CancelImport'))$('v54CancelImport').onclick=()=>{showImport=false;draw()};if($('v54ImportNow'))$('v54ImportNow').onclick=()=>{collect();const raw=$('v54BulkText').value||'';for(const line of raw.split(/\r?\n/).map(x=>x.trim()).filter(Boolean)){const [call,group,division,...desc]=line.split('|').map(x=>x.trim());const c=String(call||'').toUpperCase();if(!c)continue;const existing=svc.callsignDirectory.find(x=>String(x.callsign).toUpperCase()===c);if(existing){existing.group=group||existing.group;existing.division=division||existing.division;existing.description=desc.join(' | ')||existing.description}else svc.callsignDirectory.push({id:'cs-'+Date.now()+'-'+Math.random().toString(36).slice(2),callsign:c,group:group||'General',division:division||'',description:desc.join(' | '),active:true})}showImport=false;draw()};document.querySelectorAll('[data-v54-del]').forEach(b=>b.onclick=()=>{collect();svc.callsignDirectory.splice(+b.dataset.v54Del,1);draw()});
    const filter=()=>{const q=($('v54CallsignSearch').value||'').toLowerCase(),g=$('v54GroupFilter').value,s=$('v54StateFilter').value;document.querySelectorAll('[data-v54-row]').forEach(row=>{const i=row.dataset.v54Row,hay=[`[data-v54-call="${i}"]`,`[data-v54-group="${i}"]`,`[data-v54-div="${i}"]`,`[data-v54-desc="${i}"]`].map(sel=>document.querySelector(sel)?.value||'').join(' ').toLowerCase();const grp=document.querySelector(`[data-v54-group="${i}"]`)?.value||'';const assigned=row.dataset.assigned==='1';const active=!!document.querySelector(`[data-v54-active="${i}"]`)?.checked;row.style.display=(!q||hay.includes(q))&&(!g||grp===g)&&(!s||(s==='active'&&active)||(s==='assigned'&&assigned)||(s==='free'&&!assigned))?'grid':'none'})};$('v54CallsignSearch').oninput=filter;$('v54GroupFilter').onchange=filter;$('v54StateFilter').onchange=filter;
    $('v54SaveCallsigns').onclick=async()=>{collect();const seen=new Set(),dupes=[];for(const r of svc.callsignDirectory){if(seen.has(r.callsign))dupes.push(r.callsign);seen.add(r.callsign)}if(dupes.length)return alert('Duplicate callsigns: '+[...new Set(dupes)].join(', '));await saveAll();notify('Manual callsigns saved');draw()};
   }
  };
  draw();
 }catch(e){errorView('Services / Ranks / Callsigns',e)}
};

renderFleet=async function(){
 try{
  const [fd,sd,od]=await Promise.all([api('/api/admin/fleet'),api('/api/admin/services').catch(()=>({services:[]})),api('/api/admin/operational').catch(()=>({stations:[]}))]);
  let fleet=fd.fleet||[],services=sd.services||fd.services||[],stations=od.stations||[],selected=fleet[0]?.id||'',filterService='all',query='';
  const serviceName=id=>services.find(s=>s.id===id)?.name||id||'Unassigned';
  const draw=()=>{const visible=fleet.filter(v=>(filterService==='all'||v.serviceId===filterService)&&(!query||[v.callsign,v.name,v.type,v.station,v.registration,v.status].join(' ').toLowerCase().includes(query)));const v=fleet.find(x=>x.id===selected)||visible[0]||fleet[0]||null;if(v)selected=v.id;const counts={available:fleet.filter(x=>String(x.status).toLowerCase()==='available').length,deployed:fleet.filter(x=>String(x.status).toLowerCase()==='deployed').length,maintenance:fleet.filter(x=>['maintenance','workshop','off-run'].includes(String(x.status).toLowerCase())).length};setContent(`<div class="v54FleetShell"><section class="card v54FleetDirectory"><div class="sectionHead"><div><div class="eyebrow">FLEET & ASSET DIRECTORY</div><h3>Vehicles / Appliances</h3><p>SFRS, NFRS, Police Scotland and Scottish Ambulance fleet in one directory.</p></div><button id="v54NewVehicle">+ ADD VEHICLE</button></div><div class="v54MetricRow"><div><b>${fleet.length}</b><span>Total</span></div><div><b>${counts.available}</b><span>Available</span></div><div><b>${counts.deployed}</b><span>Deployed</span></div><div><b>${counts.maintenance}</b><span>Off run / workshop</span></div></div><div class="v54DirectoryTools"><input id="v54FleetSearch" placeholder="Search callsign, vehicle, station or registration" value="${esc(query)}"><select id="v54FleetService"><option value="all">All services</option>${services.map(s=>`<option value="${esc(s.id)}" ${filterService===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="v54FleetCards">${visible.map(x=>`<button class="v54FleetCard ${x.id===selected?'active':''}" data-v54-fleet="${esc(x.id)}"><div><span class="v54FleetCallsign">${esc(x.callsign||'NO CALLSIGN')}</span><b>${esc(x.name||x.type||'Vehicle')}</b><small>${esc(serviceName(x.serviceId))} · ${esc(x.station||'No home station')}</small></div><span class="statusBadge ${String(x.status).toLowerCase()==='available'?'ok':String(x.status).toLowerCase()==='deployed'?'warn':'off'}">${esc(x.status||'available')}</span></button>`).join('')||'<div class="emptyState">No vehicles match the current filter.</div>'}</div></section><section class="card v54FleetEditor">${v?`<div class="sectionHead"><div><div class="eyebrow">VEHICLE RECORD</div><h3>${esc(v.callsign||'New Vehicle')}</h3><p>${esc(v.name||v.type||'Fleet asset')}</p></div><div class="buttonGroup"><button id="v54SaveFleet">SAVE VEHICLE</button><button id="v54DeleteVehicle" class="danger">DELETE</button></div></div><div class="v54VehicleHeader"><div><span>Current status</span><strong>${esc(v.status||'available')}</strong></div><div><span>Home</span><strong>${esc(v.station||'Not assigned')}</strong></div><div><span>Service</span><strong>${esc(serviceName(v.serviceId))}</strong></div></div><div class="v54VehicleForm"><label>Service<select id="vfService">${services.map(s=>`<option value="${esc(s.id)}" ${v.serviceId===s.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Callsign / Fleet number<input id="vfCallsign" value="${esc(v.callsign||'')}"></label><label>Vehicle name<input id="vfName" value="${esc(v.name||'')}"></label><label>Vehicle type<input id="vfType" value="${esc(v.type||'')}"></label><label>Registration<input id="vfRegistration" value="${esc(v.registration||'')}"></label><label>Home station / base<select id="vfStation"><option value="">Not assigned</option>${stations.filter(st=>!v.serviceId||(st.serviceId||'fire')===v.serviceId).map(st=>`<option value="${esc(st.name)}" ${st.name===v.station?'selected':''}>${esc(st.name)}</option>`).join('')}</select></label><label>Status<select id="vfStatus">${['available','deployed','standby','training','maintenance','workshop','off-run','retired'].map(s=>`<option value="${s}" ${s===String(v.status||'available').toLowerCase()?'selected':''}>${s}</option>`).join('')}</select></label><label>Mileage<input id="vfMileage" type="number" min="0" value="${Number(v.mileage||0)}"></label><label>Next service / inspection<input id="vfServiceDate" type="date" value="${esc(v.nextServiceDate||'')}"></label><label>MOT / inspection expiry<input id="vfMot" type="date" value="${esc(v.motExpiry||'')}"></label><label class="wide">Capabilities / equipment<input id="vfCapabilities" value="${esc((v.capabilities||v.skills||[]).join(', '))}" placeholder="BA, RTC, Water Rescue, Roads Policing, HART..."></label><label class="wide">Qualifications required<input id="vfQualifications" value="${esc((v.requiredQualifications||[]).join(', '))}" placeholder="Emergency Response Driver, BA..."></label><label class="wide">Defects / off-run reason<textarea id="vfDefects" rows="3">${esc(v.defects||'')}</textarea></label><label class="wide">Fleet notes<textarea id="vfNotes" rows="4">${esc(v.notes||'')}</textarea></label></div>`:'<div class="emptyState"><strong>No vehicle selected</strong><span>Add or select a fleet record.</span></div>'}</section></div>`);document.querySelectorAll('[data-v54-fleet]').forEach(b=>b.onclick=()=>{selected=b.dataset.v54Fleet;draw()});$('v54FleetSearch').oninput=e=>{query=e.target.value.toLowerCase();draw()};$('v54FleetService').onchange=e=>{filterService=e.target.value;draw()};$('v54NewVehicle').onclick=()=>{const serviceId=filterService==='all'?(services[0]?.id||'fire'):filterService;const nv={id:'vehicle-'+Date.now(),serviceId,callsign:'',name:'New Vehicle',type:'',station:'',status:'available',registration:'',mileage:0,capabilities:[],requiredQualifications:[],defects:'',notes:'',active:true};fleet.unshift(nv);selected=nv.id;draw()};if(v){$('v54DeleteVehicle').onclick=()=>{if(!confirm(`Delete ${v.callsign||v.name||'this vehicle'}?`))return;fleet=fleet.filter(x=>x!==v);selected=fleet[0]?.id||'';saveFleet().then(draw)};$('v54SaveFleet').onclick=async()=>{v.serviceId=$('vfService').value;v.callsign=$('vfCallsign').value.trim().toUpperCase();v.name=$('vfName').value.trim();v.type=$('vfType').value.trim();v.registration=$('vfRegistration').value.trim().toUpperCase();v.station=$('vfStation').value;v.status=$('vfStatus').value;v.mileage=Number($('vfMileage').value||0);v.nextServiceDate=$('vfServiceDate').value;v.motExpiry=$('vfMot').value;v.capabilities=$('vfCapabilities').value.split(',').map(x=>x.trim()).filter(Boolean);v.skills=[...v.capabilities];v.requiredQualifications=$('vfQualifications').value.split(',').map(x=>x.trim()).filter(Boolean);v.defects=$('vfDefects').value.trim();v.notes=$('vfNotes').value.trim();await saveFleet();notify('Vehicle record saved');draw()}}};
  const saveFleet=async()=>api('/api/admin/fleet',{method:'POST',body:JSON.stringify({fleet})});draw();
 }catch(e){errorView('Fleet / Vehicles',e)}
};

// ============================================================
// Guardian v55 — Patrol Booking & Duty Assignment Studio
// ============================================================
function v55DateInput(value){if(!value)return '';const d=new Date(value);if(!Number.isFinite(d.getTime()))return String(value).slice(0,16);const pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`}
function v55IsoFromInput(value){if(!value)return '';const d=new Date(value);return Number.isFinite(d.getTime())?d.toISOString():value}
renderPatrols=async function(){
 try{
  const [d,dc]=await Promise.all([api('/api/admin/patrols'),api('/api/admin/discord/channels').catch(()=>({channels:[]}))]);
  let patrols=d.patrols||[],services=d.services||[],users=d.users||[],fleet=d.fleet||[],channels=dc.channels||[],selected=patrols[0]?.id||'',mode='details';
  const serviceName=id=>services.find(s=>s.id===id)?.name||id||'Joint / All';
  const userFor=b=>users.find(u=>u.username===b.username)||null;
  const eligibleServices=u=>{const ids=[...new Set((u?.serviceAssignments||[]).map(a=>a.serviceId).filter(Boolean))];return ids.length?ids:['police']};
  const eligibleDivisions=(u,sid)=>{const x=[...new Set((u?.serviceAssignments||[]).filter(a=>a.serviceId===sid).map(a=>a.division).filter(Boolean))];return x.length?x:(sid==='police'?['Response']:[])};
  const callsigns=(sid,division)=>{const s=services.find(x=>x.id===sid);const rows=(s?.callsignDirectory||[]).filter(x=>x.active!==false&&x.callsign);return rows.filter(x=>!division||!x.division||x.division===division)};
  const vehicles=sid=>fleet.filter(v=>!sid||v.serviceId===sid).filter(v=>!['retired'].includes(String(v.status||'').toLowerCase()));
  const attending=p=>(p.bookings||[]).filter(b=>['attending','booked'].includes(String(b.status)));
  const declined=p=>(p.bookings||[]).filter(b=>String(b.status)==='not-attending');
  const draw=()=>{
   const p=patrols.find(x=>x.id===selected)||patrols[0]||null;if(p)selected=p.id;
   setContent(`<div class="v55PatrolShell">
    <aside class="card v55PatrolRail"><div class="sectionHead"><div><div class="eyebrow">PATROL OPERATIONS</div><h3>Events</h3></div><button id="v55NewPatrol">+ NEW</button></div>
    <div class="v55PatrolList">${patrols.map(x=>`<button class="v55PatrolPick ${x.id===selected?'active':''}" data-v55-patrol="${esc(x.id)}"><span><b>${esc(x.title||'Official Patrol')}</b><small>${esc(x.startsAt?new Date(x.startsAt).toLocaleString():'Date TBC')}</small></span><i class="statusBadge ${x.bookingsClosed?'off':'ok'}">${x.bookingsClosed?'CLOSED':'OPEN'}</i><em>${attending(x).length} attending</em></button>`).join('')||'<div class="emptyState">No patrols created yet.</div>'}</div></aside>
    <main class="card v55PatrolMain">${p?`<div class="sectionHead"><div><div class="eyebrow">OFFICIAL FIVEM PATROL</div><h2>${esc(p.title||'Official Patrol')}</h2><p>${esc(serviceName(p.serviceId))} · ${attending(p).length} attending · ${declined(p).length} not attending</p></div><div class="buttonGroup"><button id="v55PublishDiscord" class="secondary">${p.discordMessageId?'UPDATE DISCORD':'SEND TO DISCORD'}</button><button id="v55ToggleBookings" class="${p.bookingsClosed?'secondary':'danger'}">${p.bookingsClosed?'REOPEN BOOKINGS':'CLOSE BOOKINGS'}</button></div></div>
    <div class="settingsSubtabs v55PatrolTabs"><button class="settingsSubtab ${mode==='details'?'active':''}" data-v55-mode="details">EVENT DETAILS<small>Schedule & Discord</small></button><button class="settingsSubtab ${mode==='bookings'?'active':''}" data-v55-mode="bookings">BOOKINGS<small>${attending(p).length} attending</small></button><button class="settingsSubtab ${mode==='assignments'?'active':''}" data-v55-mode="assignments">DUTY ASSIGNMENTS<small>${p.bookingsClosed?'Ready to assign':'Close bookings first'}</small></button></div>
    ${mode==='details'?`<div class="v55EventGrid"><label>Patrol title<input id="v55Title" value="${esc(p.title||'Official Patrol')}"></label><label>Operation type<select id="v55Service"><option value="joint" ${p.serviceId==='joint'?'selected':''}>Joint / Multi-service</option>${services.filter(s=>s.enabled!==false).map(s=>`<option value="${esc(s.id)}" ${s.id===p.serviceId?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label>Patrol starts<input id="v55Starts" type="datetime-local" value="${esc(v55DateInput(p.startsAt))}"></label><label>Bookings close<input id="v55Closes" type="datetime-local" value="${esc(v55DateInput(p.bookingClosesAt))}"><small>Defaults to one hour before patrol.</small></label><label>Maximum attendees<input id="v55Max" type="number" min="0" value="${Number(p.maxSlots||0)}"><small>0 = unlimited</small></label><label>Discord channel<select id="v55DiscordChannel"><option value="">Use default patrol channel</option>${channels.map(c=>`<option value="${esc(c.id)}" ${String(c.id)===String(p.discordChannelId||'')?'selected':''}>#${esc(c.name)}</option>`).join('')}</select></label><label class="wide">Patrol briefing<textarea id="v55Briefing" rows="7" placeholder="Briefing time, meeting point, patrol information, server notes…">${esc(p.briefing||'')}</textarea></label></div><div class="v55InfoStrip"><div><b>Member booking</b><span>Members only choose Attending or Not Attending. They do not choose service, division or callsign.</span></div><div><b>Automatic close</b><span>Guardian closes booking one hour before the patrol unless staff close it earlier.</span></div></div><div class="saveBar"><button id="v55DeletePatrol" class="danger">DELETE EVENT</button><button id="v55SavePatrol">SAVE EVENT</button></div>`:''}
    ${mode==='bookings'?`<div class="v55BookingSummary"><div><b>${attending(p).length}</b><span>Attending</span></div><div><b>${declined(p).length}</b><span>Not attending</span></div><div><b>${p.bookingsClosed?'Closed':'Open'}</b><span>Booking status</span></div><div><b>${p.maxSlots||'∞'}</b><span>Capacity</span></div></div><div class="v55PeopleList">${(p.bookings||[]).map(b=>`<article class="v55PersonRow"><div class="avatarMini">${esc((b.displayName||b.username||'?').slice(0,1).toUpperCase())}</div><div><b>${esc(b.displayName||b.username)}</b><small>${esc(b.username)}${b.source?' · '+esc(b.source.toUpperCase()):''}</small></div><span class="statusBadge ${['attending','booked'].includes(String(b.status))?'ok':'off'}">${['attending','booked'].includes(String(b.status))?'ATTENDING':'NOT ATTENDING'}</span><small>${b.respondedAt?new Date(b.respondedAt).toLocaleString():b.bookedAt?new Date(b.bookedAt).toLocaleString():'—'}</small></article>`).join('')||'<div class="emptyState">Nobody has responded yet.</div>'}</div>`:''}
    ${mode==='assignments'?(!p.bookingsClosed?`<div class="v55Locked"><b>Duty assignment is locked</b><p>Close bookings first. This prevents callsigns/divisions being allocated while people are still changing attendance.</p><button id="v55CloseFromAssignment">CLOSE BOOKINGS NOW</button></div>`:`<div class="v55AssignmentIntro"><div><div class="eyebrow">STAFF DUTY MANAGEMENT</div><h3>Assign attending members</h3><p>Only staff assign service, approved division, callsign and optional vehicle. Rank is not changed here.</p></div><span class="statusBadge off">BOOKINGS CLOSED</span></div><div class="v55AssignmentTable"><div class="v55AssignmentHead"><span>Member</span><span>Service</span><span>Division</span><span>Callsign</span><span>Vehicle</span><span></span></div>${attending(p).map((b,i)=>{const u=userFor(b),current=b.deployment||{},svcs=eligibleServices(u),sid=current.serviceId&&svcs.includes(current.serviceId)?current.serviceId:svcs[0]||'police',divs=eligibleDivisions(u,sid),div=current.division&&divs.includes(current.division)?current.division:(divs[0]||''),cs=callsigns(sid,div),vs=vehicles(sid);return `<div class="v55AssignmentRow" data-v55-assignment="${i}" data-user="${esc(b.username)}"><div><b>${esc(b.displayName||b.username)}</b><small>${esc(u?.serviceAssignments?.find(a=>a.serviceId===sid)?.rank||'Member')}</small></div><select data-v55-service="${i}">${svcs.map(x=>`<option value="${esc(x)}" ${x===sid?'selected':''}>${esc(serviceName(x))}</option>`).join('')}</select><select data-v55-division="${i}">${divs.map(x=>`<option value="${esc(x)}" ${x===div?'selected':''}>${esc(x)}</option>`).join('')}${!divs.length?'<option value="">No division</option>':''}</select><select data-v55-callsign="${i}"><option value="">Unassigned</option>${cs.map(x=>`<option value="${esc(x.callsign)}" ${x.callsign===current.callsign?'selected':''}>${esc(x.callsign)}${x.group?' · '+esc(x.group):''}</option>`).join('')}</select><select data-v55-vehicle="${i}"><option value="">No vehicle</option>${vs.map(x=>`<option value="${esc(x.id||x.callsign)}" ${(x.id||x.callsign)===current.vehicle?'selected':''}>${esc(x.callsign||x.registration||x.name)} · ${esc(x.name||x.type||'Vehicle')}</option>`).join('')}</select><button data-v55-assign="${i}">${current.assignedAt?'UPDATE':'ASSIGN'}</button></div>`}).join('')||'<div class="emptyState">No attending members to assign.</div>'}</div>`) :''}
    `:'<div class="emptyState"><strong>Create your first patrol</strong><span>Guardian will manage Discord booking, closing and staff duty assignments.</span></div>'}</main></div>`);
   document.querySelectorAll('[data-v55-patrol]').forEach(b=>b.onclick=()=>{selected=b.dataset.v55Patrol;mode='details';draw()});document.querySelectorAll('[data-v55-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.v55Mode;draw()});
   $('v55NewPatrol').onclick=()=>{const now=new Date(Date.now()+24*3600000);now.setMinutes(0,0,0);const start=now.toISOString();patrols.unshift({id:'new-'+Date.now(),title:'Official Patrol',serviceId:'joint',startsAt:start,bookingClosesAt:new Date(now.getTime()-3600000).toISOString(),briefing:'',published:true,maxSlots:0,bookings:[],bookingsClosed:false});selected=patrols[0].id;mode='details';draw()};
   if(!p)return;
   const toggle=async(action)=>{await api('/api/admin/patrols/'+encodeURIComponent(p.id)+'/bookings',{method:'POST',body:JSON.stringify({action})});notify(action==='close'?'Bookings closed':'Bookings reopened');renderPatrols()};
   if($('v55ToggleBookings'))$('v55ToggleBookings').onclick=()=>toggle(p.bookingsClosed?'open':'close');if($('v55CloseFromAssignment'))$('v55CloseFromAssignment').onclick=()=>toggle('close');
   if($('v55PublishDiscord'))$('v55PublishDiscord').onclick=async()=>{const ch=$('v55DiscordChannel')?.value||p.discordChannelId||'';await api('/api/admin/patrols/'+encodeURIComponent(p.id)+'/discord',{method:'POST',body:JSON.stringify({channelId:ch})});notify(p.discordMessageId?'Discord patrol updated':'Patrol sent to Discord');renderPatrols()};
   if($('v55SavePatrol'))$('v55SavePatrol').onclick=async()=>{const starts=v55IsoFromInput($('v55Starts').value),closes=v55IsoFromInput($('v55Closes').value);const payload={...p,title:$('v55Title').value.trim(),serviceId:$('v55Service').value,startsAt:starts,bookingClosesAt:closes,maxSlots:Number($('v55Max').value||0),discordChannelId:$('v55DiscordChannel').value,briefing:$('v55Briefing').value.trim(),published:true};if(String(p.id).startsWith('new-'))delete payload.id;const r=await api('/api/admin/patrols',{method:'POST',body:JSON.stringify({patrol:payload})});notify('Patrol saved');selected=r.patrol.id;renderPatrols()};
   if($('v55DeletePatrol'))$('v55DeletePatrol').onclick=async()=>{if(String(p.id).startsWith('new-')){patrols=patrols.filter(x=>x!==p);selected=patrols[0]?.id||'';draw();return}if(!confirm('Delete this patrol?'))return;await api('/api/admin/patrols/'+encodeURIComponent(p.id),{method:'DELETE'});notify('Patrol deleted');renderPatrols()};
   if(mode==='assignments'&&p.bookingsClosed){document.querySelectorAll('[data-v55-service]').forEach(sel=>sel.onchange=()=>{const i=+sel.dataset.v55Service,b=attending(p)[i],u=userFor(b),sid=sel.value,divs=eligibleDivisions(u,sid),divSel=document.querySelector(`[data-v55-division="${i}"]`),csSel=document.querySelector(`[data-v55-callsign="${i}"]`),vSel=document.querySelector(`[data-v55-vehicle="${i}"]`);divSel.innerHTML=divs.length?divs.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join(''):'<option value="">No division</option>';const refresh=()=>{const div=divSel.value;csSel.innerHTML='<option value="">Unassigned</option>'+callsigns(sid,div).map(x=>`<option value="${esc(x.callsign)}">${esc(x.callsign)}${x.group?' · '+esc(x.group):''}</option>`).join('');vSel.innerHTML='<option value="">No vehicle</option>'+vehicles(sid).map(x=>`<option value="${esc(x.id||x.callsign)}">${esc(x.callsign||x.registration||x.name)} · ${esc(x.name||x.type||'Vehicle')}</option>`).join('')};divSel.onchange=refresh;refresh()});document.querySelectorAll('[data-v55-assign]').forEach(btn=>btn.onclick=async()=>{const i=+btn.dataset.v55Assign,b=attending(p)[i],serviceId=document.querySelector(`[data-v55-service="${i}"]`).value,division=document.querySelector(`[data-v55-division="${i}"]`).value,callsign=document.querySelector(`[data-v55-callsign="${i}"]`).value,vehicle=document.querySelector(`[data-v55-vehicle="${i}"]`).value;await api('/api/admin/patrols/'+encodeURIComponent(p.id)+'/deployment',{method:'POST',body:JSON.stringify({username:b.username,serviceId,division,callsign,vehicle})});notify(`Duty assigned to ${b.displayName||b.username}`);renderPatrols()})}
  };
  draw();
 }catch(e){errorView('Operations & Deployment',e)}
};
